from decimal import Decimal


def _value(source: dict | None, key: str):
    if not source:
        return ""
    value = source.get(key, "")
    return "" if value is None else value


def _text(source: dict | None, key: str) -> str:
    value = _value(source, key)
    return str(value)


def _number(value) -> Decimal:
    if value is None or value == "":
        return Decimal("0")
    return Decimal(str(value))


def _date_eq(value, literal: str) -> bool:
    value = str(value)
    if value == "00000000" or literal == "00000000":
        return value == literal == "00000000"
    return value == literal


def _date_ge(value, other: str) -> bool:
    value = str(value)
    other = str(other)
    if value == "00000000" or other == "00000000":
        return False
    return value >= other


def _error(code: str, message: str, severity: str = "BLOCK") -> dict:
    return {"code": code, "message": message, "severity": severity}


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    errors: list[dict] = []

    amount = _number(_value(record, "AMT"))
    status = _text(record, "STAT_CD")
    lost_reason = _text(record, "LOST_RSN")
    close_date = _text(record, "CLOSE_DT")
    stage_pct = _number(_value(record, "STAGE_PCT"))

    if event in ("INSERT", "UPDATE"):
        if not (amount >= Decimal("0")):
            errors.append(_error("E3001", "Amount negative"))

    if event in ("INSERT", "UPDATE"):
        if not (not (status == "W" and amount == Decimal("0"))):
            errors.append(_error("E3002", "Won opportunity requires amount"))

    if event in ("INSERT", "UPDATE"):
        if not (not (status == "L" and lost_reason == "")):
            errors.append(_error("E3003", "Lost reason required"))

    if event in ("INSERT", "UPDATE"):
        if not (not (status == "W" and _date_eq(close_date, "00000000"))):
            errors.append(_error("E3004", "Won opportunity requires close date"))

    if event == "UPDATE":
        old_status = _text(old, "STAT_CD")
        if not (not (old_status == "W" and status != "W")):
            errors.append(_error("E3005", "Cannot reopen a won opportunity"))

    if event in ("INSERT", "UPDATE"):
        stage_consistent = (
            (status == "P" and stage_pct == Decimal("10"))
            or (status == "Q" and stage_pct == Decimal("25"))
            or (status == "N" and stage_pct == Decimal("60"))
            or (status == "W" and stage_pct == Decimal("100"))
            or (status == "L" and stage_pct == Decimal("0"))
        )
        if not stage_consistent:
            errors.append(
                _error("E3006", "Stage percent inconsistent with status")
            )

    if event == "INSERT":
        if not (_date_eq(close_date, "00000000") or _date_ge(close_date, today)):
            errors.append(_error("E3007", "Close date in past", "WARN"))

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
